	q := []*TreeNode{root}
	i := 1
	for len(q) > 0 && i < len(vals) {
		cur := q[0]
		q = q[1:]
		if i < len(vals) {
			if vals[i] != "null" {
				cur.Left = &TreeNode{Val: atoi(vals[i])}
				q = append(q, cur.Left)
			}
			i++
		}
		if i < len(vals) {
