func dump(root *TreeNode) string {
	if root == nil {
		return "[]"
	}
	out := []string{}
	q := []*TreeNode{root}
	for len(q) > 0 {
		n := q[0]
		q = q[1:]
		if n == nil {
			out = append(out, "null")
		} else {
			out = append(out, strconv.Itoa(n.Val))
			q = append(q, n.Left, n.Right)
		}
	}
	for len(out) > 0 && out[len(out)-1] == "null" {
		out = out[:len(out)-1]
	}
	return "[" + strings.Join(out, ",") + "]"
}

func main() {
	data, _ := os.ReadFile("/dev/stdin")
	root := build(tokens(string(data)))
	vals := []int{}
	var inorder func(node *TreeNode)
	inorder = func(node *TreeNode) {
		if node == nil {
			return
		}
		inorder(node.Left)
		vals = append(vals, node.Val)
		inorder(node.Right)
	}
	inorder(root)
	var buildBal func(lo, hi int) *TreeNode
	buildBal = func(lo, hi int) *TreeNode {
		if lo > hi {
			return nil
		}
		mid := (lo + hi) / 2
		node := &TreeNode{Val: vals[mid]}
		node.Left = buildBal(lo, mid-1)
		node.Right = buildBal(mid+1, hi)
		return node
	}
	fmt.Println(dump(buildBal(0, len(vals)-1)))
}

