func solveSudoku(board [][]byte) {
	var rows, cols, boxes [9][9]bool
	for i := 0; i < 9; i++ {
		for j := 0; j < 9; j++ {
			c := board[i][j]
			if c != '.' {
				k := c - '1'
				rows[i][k] = true
				cols[j][k] = true
				boxes[i/3*3+j/3][k] = true
			}
		}
	}
	var dfs func() bool
	dfs = func() bool {
		for i := 0; i < 9; i++ {
			for j := 0; j < 9; j++ {
				if board[i][j] != '.' {
					continue
				}
				b := i/3*3 + j/3
				for c := byte('1'); c <= '9'; c++ {
					k := c - '1'
					if rows[i][k] || cols[j][k] || boxes[b][k] {
						continue
					}
					board[i][j] = c
					rows[i][k], cols[j][k], boxes[b][k] = true, true, true
					if dfs() {
						return true
					}
					board[i][j] = '.'
					rows[i][k], cols[j][k], boxes[b][k] = false, false, false
				}
				return false
			}
		}
		return true
	}
	dfs()
}

